"""Privacy manager creation for CALM vs Mantle endpoint shapes."""

from __future__ import annotations

from pydantic import BaseModel, ConfigDict

from rasa.core.config.available_endpoints import AvailableEndpoints


class PrivacyManagerBootstrap(BaseModel):
    """Whether to create a privacy manager and which endpoints to pass."""

    model_config = ConfigDict(arbitrary_types_allowed=True, frozen=True)

    should_create: bool
    endpoints_for_privacy: AvailableEndpoints


def resolve_privacy_manager_bootstrap(
    endpoints: AvailableEndpoints,
    *,
    mantle_project: bool,
) -> PrivacyManagerBootstrap:
    """Return creation flag and endpoints with Mantle-incompatible privacy stripped."""
    should_create = bool(endpoints.privacy) or mantle_project
    endpoints_for_privacy = endpoints
    if mantle_project:
        privacy_free = endpoints.to_dict()
        privacy_free["privacy"] = None
        endpoints_for_privacy = AvailableEndpoints.from_dict(privacy_free)

    return PrivacyManagerBootstrap(
        should_create=should_create,
        endpoints_for_privacy=endpoints_for_privacy,
    )
